def create_bt_colorbar(bt):

    cax = axes([0.82, 0.2, 0.025, 0.6]) 
    ticks = range(210,320,20)
    cbar = colorbar(bt, orientation='vertical', format='%2.0f', ticks=ticks, cax=cax)
    cbar.set_label(r'10.7 $\mathrm{\mu}$m Brightness Temperature (K)', fontsize=8)
    cbar.ax.set_yticklabels(ticks, fontsize=8) #[::-1],fontsize=8)
    cbar.ax.invert_yaxis()

    return cbar

#------------------------------------

def build_basic_figure_with_map(basemap):
# draws geographic features on map
# labels=[left,right,top,bottom])

    # create the empty figure
    figure = plt.figure()
    ax = figure.add_subplot(111)

    if basemap is not None:
        basemap.drawcoastlines(linewidth=0.5)
        basemap.drawcountries(linewidth=0.5)
        basemap.drawstates(linewidth=0.5)
        basemap.drawmeridians(np.arange(0,360,10), fontsize=8, labels=[False,False,False,True]) # labels=[left,right,top,bottom])
        basemap.drawparallels(np.arange(-90,90,10), fontsize=8, labels=[True,False,False,False]) # labels=[left,right,top,bottom])    
   
    return ax, figure

#------------------------------------

def create_basemap(minLat, maxLat, minLon, maxLon, sat, time):
# Creates a basemap onto which to plot data

    # FIND CENTER LATITUDE AND LONGITUDE
    if antimeridian:
        # calculate ranges and center lon / lat
        rangeLon = (360 + maxLon) - minLon
        if rangeLon > 360:
            rangeLon = maxLon - minLon
        rangeLat = maxLat - minLat
        centerLat = minLat  + (rangeLat / 2.0)
        centerLon = minLon + (rangeLon / 2.0)
        # convert lon and lat to meters for creating basemap
        centerLatRadians = centerLat * (pi/180)
        latRangemeters = rangeLat * 40008000. / 360.
        lonRangemeters = rangeLon * 40075160 * cos(centerLatRadians) / 360
    else:
        rangeLat = maxLat - minLat
        rangeLon = maxLon - minLon
        centerLat = minLat + (rangeLat/2.0)
        centerLon = minLon + (rangeLon/2.0)

    if polar:

        # The longitude lon_0 is at 6-o'clock, and the
        # latitude circle boundinglat is tangent to the edge
        # of the map at lon_0. Default value of lat_ts
        # (latitude of true scale) is pole.
        #proj = 'npstere'
        #basemapObject = Basemap(projection=proj, boundinglat=minLat,lon_0=centerLon,
        #                        lat_ts=centerLat,resolution='l')

        proj = 'npstere' if centerLat > 0. else 'spstere'
        prj = Basemap(projection=proj, lon_0=centerLon, lat_0=centerLat,
                          boundinglat=0, resolution='l')
        lons = [minLon, maxLon, minLon, maxLon, centerLon, centerLon]
        lats = [minLat, minLat, maxLat, maxLat, minLat, maxLat]
        x, y = prj(lons, lats)
        ll_lon, ll_lat = prj(min(x), min(y), inverse=True)
        ur_lon, ur_lat = prj(max(x), max(y), inverse=True)
        basemapObject = Basemap(projection='stere', lat_0=centerLat, lon_0=centerLon,
                           llcrnrlon=ll_lon, llcrnrlat=ll_lat,
                           urcrnrlon=ur_lon, urcrnrlat=ur_lat, resolution = 'l')

    else:

        proj = 'lcc' # Lambert Conformal projection
        if antimeridian:
            basemapObject = Basemap(projection = proj, 
                                    width=lonRangemeters,height=latRangemeters,
                                    lat_0 = centerLat, lon_0 = centerLon,
                                    lat_1 = centerLat, resolution = 'l')
    
        else:
            basemapObject = Basemap(projection = proj, llcrnrlat = minLat, urcrnrlat = maxLat,
                                    llcrnrlon = minLon, urcrnrlon = maxLon,
                                    lat_0 = centerLat, lon_0 = centerLon,
                                    resolution = 'l')

    return basemapObject

#------------------------------------

def draw_contour_with_basemap (basemap, data, lonData, latData, **kwargs):

    # translate into the coordinate system of the basemap
    tempX, tempY = basemap(lonData, latData)

    # show the plot if there is data
    if (data is not None) :

        p = basemap.contourf(tempX, tempY, data, **kwargs)

    return p

