def plot_cloudmask(outdir, imagedir, filename, sat, date, lat, lon, minLat, maxLat, minLon, maxLon, var, title):

    # 9999 - No Mask Determined 
    # 1 - Cloudy 
    # 2 - Undetermined 
    # 3 - Confident Clear
    # 4 - High Confident Clear

    # set levels at which data should be contoured
    levels = [0, 1.5, 2.5, 3.5, 4.5]

    infile = outdir + '/' + filename
    time = filename.split('.')[2]

    # create basemap, figure, and subplot instances
    basemap = create_basemap(minLat, maxLat, minLon, maxLon, sat, time)
    ax, figure = build_basic_figure_with_map (basemap)

    # read in data
    cloudmask = read_2d_variable(infile, 'MODIS_Cloud_Mask')

    # plot data on map 
    cs = draw_contour_with_basemap(basemap, cloudmask, lon, lat, levels=levels, cmap = cmap_cloudmask)

    figure.subplots_adjust(bottom=0.15)

    # create legend - bbox = (x,y,width,height of the bbox)
    proxy = [plt.Rectangle((0,0),1,1,fc = pc.get_facecolor()[0]) for pc in cs.collections]
    plt.legend(proxy, ['Cloud', 'Uncertain', 'Clear', 'High Confident Clear'], bbox_to_anchor=(0.5, -0.13, 0., 0.),\
                      loc=8, ncol=5, prop={'size':11.})

    # set figure title and subtitle
    figure.suptitle(title, fontweight='bold')
    ax.set_title('%(sat)s %(date)s %(time)s UTC' % locals(), fontsize = 10, ha = 'center', fontstyle = 'italic')

    plt.tight_layout(pad=4.0)

    # save figure to a file
    figure.savefig('%(imagedir)s/%(sat)s_%(date)s_%(time)s_CloudMask.png' % locals(), dpi=figureDPI)
    
    close(figure)

