def plot_ctt(outdir, imagedir, filename, sat, date, minLat, maxLat, minLon, maxLon):

    # set levels at which data should be contoured
    levels = np.arange(190,330,5)

    infile = '%(outdir)s/%(filename)s' % locals()
    time = filename.split('.')[2]

    # create basemap, figure, and subplot instances
    basemap = create_basemap(minLat, maxLat, minLon, maxLon, sat, time)
    ax, figure = build_basic_figure_with_map (basemap)
    
    # read in data
    ctt, units = read_2d_variable(infile, 'Cloud_Top_Temperature')
    lat, lon = read_latlon(infile)
                    
    # plot data on map 
    draw_contour_with_basemap(basemap, ctt, lon, lat, levels=levels)
 
    # create colorbar
